dark_mode.overrides_css:
[data-bs-theme="dark"] body { background-color: var(--sd-dark); color: #f3f4f6; }
[data-bs-theme="dark"] .card-portfolio-title { color: #ffffff; }
[data-bs-theme="dark"] .text-muted { color: #9ca3af !important; }
[data-bs-theme="dark"] header .navbar { background-color: rgba(0, 0, 0, 0.8) !important; }
